import java.nio.file.*;import java.nio.charset.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;
/** Existing SELECTs only: derived projections preserve old column labels, arguments and player-table reads. */
public final class SourceLegacyEquipmentSqlMethods {
 static final String P="local/lito381/server/";static String armor,weapon;static final List<String> TYPES=List.of(P+"LegacyMySqlRepository",P+"LegacyInventoryWeightLoader");
 static String translate(String type,String method,String value){String next=value;if(type.endsWith("LegacyInventoryWeightLoader")&&method.equals("load")&&value.startsWith("SELECT i.id, i.item_id, i.count,"))next=value.replace("LEFT JOIN %s a ON","LEFT JOIN (SELECT "+armor+" FROM %s) a ON").replace("LEFT JOIN %s w ON","LEFT JOIN (SELECT "+weapon+" FROM %s) w ON");
  if(type.endsWith("LegacyMySqlRepository")){if(method.equals("equippedFireResistance")&&value.startsWith("SELECT COALESCE(SUM(a.defense_fire)"))next=value.replace("JOIN %s a ON","JOIN (SELECT "+armor+" FROM %s) a ON");if(method.equals("rewardArmorDefinition")&&value.startsWith("SELECT item_id,COALESCE(NULLIF(name,"))next=value.replace(" FROM \u0001 WHERE item_id=?"," FROM (SELECT "+armor+" FROM \u0001) native_source_armor WHERE item_id=?");if(method.equals("sourceInventorySql")){if(value.contains("'armor' AS item_kind"))next=value.replace("JOIN \u0001 a ON","JOIN (SELECT "+armor+" FROM \u0001) a ON");if(value.contains("'weapon' AS item_kind"))next=value.replace("JOIN \u0001 w ON","JOIN (SELECT "+weapon+" FROM \u0001) w ON");}}
  if(value.chars().filter(x->x==1||x==2).count()!=next.chars().filter(x->x==1||x==2).count()||value.split("%s",-1).length!=next.split("%s",-1).length||value.chars().filter(x->x=='?').count()!=next.chars().filter(x->x=='?').count())throw new AssertionError("unchanged original SQL/binding/concat arguments");return next;
 }
 static int patch(ClassNode c,List<String> rows){int count=0;for(var m:c.methods)for(var n:m.instructions){if(n instanceof LdcInsnNode ldc&&ldc.cst instanceof String old){var next=translate(c.name,m.name,old);if(!next.equals(old)){ldc.cst=next;count++;rows.add(row(c.name,m.name,old,next));}}if(n instanceof InvokeDynamicInsnNode dynamic)for(int i=0;i<dynamic.bsmArgs.length;i++)if(dynamic.bsmArgs[i] instanceof String old){var next=translate(c.name,m.name,old);if(!next.equals(old)){dynamic.bsmArgs[i]=next;count++;rows.add(row(c.name,m.name,old,next));}}}return count;}
 static String row(String type,String method,String old,String next){var b=Base64.getEncoder();return type+'\t'+method+'\t'+b.encodeToString(old.getBytes(StandardCharsets.UTF_8))+'\t'+b.encodeToString(next.getBytes(StandardCharsets.UTF_8));}
 public static void main(String[]a)throws Exception{var inputs=Path.of(a[3]);armor=Files.readString(inputs.resolve("armor-projection.txt"));weapon=Files.readString(inputs.resolve("weapon-projection.txt"));var rows=new ArrayList<String>();int count=0;try(var base=new JarFile(a[1])){for(var name:TYPES){var c=FreezeAcceptedMethods.read(base,name);count+=patch(c,rows);var bytes=FreezeAcceptedMethods.bytes(c,false);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(name+".class");Files.createDirectories(p.getParent());Files.write(p,bytes);}else try(var jar=new JarFile(a[2])){if(!Arrays.equals(bytes,FreezeAcceptedMethods.bytes(FreezeAcceptedMethods.read(jar,name),false)))throw new AssertionError("exact SELECT-only projection "+name);}}if(count!=5)throw new AssertionError("exactly five original queries, six static table projections: "+count);if(a[0].equals("verify"))try(var jar=new JarFile(a[2])){var names=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(base.entries())){names.add(e.getName());var next=jar.getJarEntry(e.getName());if(next==null)throw new AssertionError("removed entry");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(next).readAllBytes()))changed.add(e.getName());}for(var e:Collections.list(jar.entries()))if(!names.contains(e.getName()))throw new AssertionError("new archive entry");if(!changed.equals(Set.of(TYPES.get(0)+".class",TYPES.get(1)+".class")))throw new AssertionError("two readonly consumer classes only");}}Files.write(Path.of(a[4]),rows);System.out.println("PASS five existing SELECTs: original bindings, player-table expressions and SQL authority unchanged; no new classes or IO paths");}
}
